const DOW_DEMAND_SHAPE: Record<Dow, number> = {
  Mon: 0.9,
  Tue: 0.9,
  Wed: 1.0,
  Thu: 1.0,
  Fri: 1.15,
  Sat: 1.25,
  Sun: 0.95,
};

/** 最小値がちょうど 1.0 になるよう全体をスケールする（相対的な形は保たれる） */
function normalizeToMinOne<K extends string>(
  shape: Record<K, number>,
): Record<K, number> {
  const values = Object.values(shape) as number[];
  const min = Math.min(...values);
  const out = {} as Record<K, number>;
  for (const [k, v] of Object.entries(shape) as Array<[K, number]>) {
    // 浮動小数の誤差で 0.9999… にならないよう 6 桁で丸める
    out[k] = Math.round(((v as number) / min) * 1e6) / 1e6;
  }
  return out;
}

