export const DEFAULT_PRICING_CONFIG: PricingConfig = {
  // ethJpy は既定値を持たない。取得できなければ実効単価を出さない。
  monthFactor: Object.fromEntries(
    Object.entries(MONTH_DEMAND_SHAPE).map(([area, months]) => [
      area,
      normalizeToMinOne(months),
    ]),
  ),
  dowFactor: normalizeToMinOne(DOW_DEMAND_SHAPE),

  specialDay: {
    // 月係数では平準化されて消えてしまう、価格が最も跳ねる数日。
    ranges: [
      {
        id: "new-year",
        label: "年末年始",
        fromMmDd: "12-28",
        toMmDd: "01-03",
        factor: 1.6,
      },
      {
        id: "golden-week",
        label: "GW",
        fromMmDd: "04-29",
        toMmDd: "05-05",
        factor: 1.4,
      },
      {
        id: "obon",
        label: "お盆",
        fromMmDd: "08-11",
        toMmDd: "08-16",
        factor: 1.35,
      },
    ],
    holidays: JP_HOLIDAYS,
    holidayFactor: 1.1,
    holidayEveFactor: 1.25,
  },

  longStayFactor: {
    "1": 1.0,
    "2": 0.95,
    "3": 0.9,
    "7": 0.85,
    "14": 0.8,
  },

  leadtimeMargin: [
    { daysLt: 7, margin: 0.2 },
    { daysLt: 14, margin: 0.1 },
    { daysLt: 30, margin: 0.05 },
  ],

  baselineRelError: {
    Low: 0.1,
    Med: 0.25,
    High: 0.5,
  },
};

function mmDd(iso: string): string {
  return iso.slice(5, 10);
}

function inMmDdRange(target: string, from: string, to: string): boolean {
  // 年をまたぐレンジ（12-28 〜 01-03）は 2 区間に分けて判定する
  if (from <= to) return target >= from && target <= to;
  return target >= from || target <= to;
}

/**
 * 年末年始・GW・お盆・連休といった特異日の割増係数。
 * 必ず 1.0 以上を返す（baseline = 年内最安 という定義を壊さないため）。
 * 複数の条件に当たる場合は掛け合わせず最大値を採る。
 */
export function resolveSpecialDayFactor(
  dateIso: string,
  cfg: PricingConfig = DEFAULT_PRICING_CONFIG,
): number {
  const candidates: number[] = [1];
  const md = mmDd(dateIso);

  for (const range of cfg.specialDay.ranges) {
    if (inMmDdRange(md, range.fromMmDd, range.toMmDd)) {
      candidates.push(range.factor);
    }
  }

  const holidays = new Set(cfg.specialDay.holidays);
  const d = parseCheckinDateJst(dateIso);
  if (d) {
    const dow = getJstDowIndex(d); // 0=Sun
    const isWeekday = dow >= 1 && dow <= 5;
    if (isWeekday && holidays.has(dateIso)) {
      candidates.push(cfg.specialDay.holidayFactor);
    }
    // 翌日が祝日の夜は連休の入り口。土曜は曜日係数で既に上がるので除く。
    const tomorrow = dateIsoJst(addDays(d, 1));
    if (dow !== 6 && holidays.has(tomorrow)) {
      candidates.push(cfg.specialDay.holidayEveFactor);
    }
  }

  return Math.max(...candidates);
}

/** チェックイン日までの残日数から、上限入札に上乗せする安全マージンを返す */
export function resolveLeadtimeMargin(
  daysUntil: number | undefined,
  cfg: PricingConfig = DEFAULT_PRICING_CONFIG,
): number {
  if (daysUntil === undefined) return 0;
  const sorted = [...cfg.leadtimeMargin].sort((a, b) => a.daysLt - b.daysLt);
  for (const item of sorted) {
    if (daysUntil < item.daysLt) return item.margin;
  }
  return 0;
}

// ===== helper: 公式ページからOG画像を解決 =====
export async function resolveOgImage(url: string): Promise<string | undefined> {
  const res = await fetch(url, {
    headers: { "User-Agent": "Mozilla/5.0 (+https://github.com/whatwg/fetch)" },
  });
  const html = await res.text();
  const m =
    html.match(
      /<meta[^>]+property=["']og:image["'][^>]+content=["']([^"]+)["']/i,
    ) ||
    html.match(
      /<meta[^>]+name=["']twitter:image["'][^>]+content=["']([^"]+)["']/i,
    );
  return m?.[1];
}

/** サムネ未設定の項目にOG画像URLを流し込む */
export async function hydrateThumbnails(
  table: Record<HouseId, HouseInfo> = HOUSE_TABLE,
) {
  const ids = Object.keys(table) as HouseId[];
  for (const id of ids) {
    const item = table[id];
    if (!item.officialThumbUrl) {
      try {
        const og = await resolveOgImage(item.officialUrl);
        if (og) item.officialThumbUrl = og;
      } catch {
        // ignore
      }
    }
  }
  return table;
}
